"""Calculator tools for Strands agents to avoid hallucinated statistics."""

import ast
import operator


from strands.tools import tool


# Safe arithmetic evaluator — replaces eval() (a code-injection sink). The
# expression here is generated by the query agent from user questions, so it
# is attacker-influenceable. We parse to an AST and walk it with an explicit
# operator allowlist: no names, calls, attributes, or comprehensions can
# appear, so RCE is structurally impossible (not merely charset-filtered).
# Exponentiation is capped to block the `9**9**9` DoS that the old charset
# check let through.
_ALLOWED_BINOPS = {
    ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
    ast.Div: operator.truediv, ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod, ast.Pow: operator.pow,
}
_ALLOWED_UNARYOPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}
_MAX_EXP = 100  # cap exponent magnitude to prevent runaway int growth / DoS


def _safe_eval(node):
    if isinstance(node, ast.Expression):
        return _safe_eval(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)):
            return node.value
        raise ValueError("only numeric constants allowed")
    if isinstance(node, ast.BinOp) and type(node.op) in _ALLOWED_BINOPS:
        left, right = _safe_eval(node.left), _safe_eval(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) > _MAX_EXP:
            raise ValueError(f"exponent too large (max {_MAX_EXP})")
        return _ALLOWED_BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in _ALLOWED_UNARYOPS:
        return _ALLOWED_UNARYOPS[type(node.op)](_safe_eval(node.operand))
    raise ValueError("unsupported expression element")


@tool
def calculate(expression: str) -> str:
    """Evaluate a mathematical expression safely. Use this for any arithmetic
    (counts, percentages, averages, scores) instead of computing in your head.
    Examples: '13/39*100', '4*13 + 3*10 + 2*16', '(13+16)/39*100'"""
    if len(expression) > 200:
        return "Error: expression too long."
    try:
        tree = ast.parse(expression, mode="eval")
        result = _safe_eval(tree)
        if isinstance(result, float):
            return f"{result:.2f}"
        return str(result)
    except ZeroDivisionError:
        return f"Error evaluating '{expression}': division by zero"
    except Exception as e:
        return f"Error evaluating '{expression}': {e}"


@tool
def count_findings(document_id: str, validation_id: str = "") -> str:
    """Get accurate counts of findings by status and severity for a validation.
    Returns exact numbers — use this instead of counting manually."""
    from app.services.validation_store import validation_store

    if validation_id:
        val = validation_store.get_validation(validation_id)
        if not val:
            return "Validation not found."
        findings = val.findings
    else:
        validations = validation_store.list_validations(document_id=document_id)
        if not validations:
            return "No validations found for this document."
        val = validations[-1]
        findings = val.findings

    if not findings:
        return "No findings in this validation."

    total = len(findings)
    by_status = {}
    by_severity = {}
    by_status_severity = {}

    for f in findings:
        status = f.status.value if hasattr(f.status, 'value') else str(f.status)
        severity = f.severity.value if hasattr(f.severity, 'value') else str(f.severity)

        by_status[status] = by_status.get(status, 0) + 1
        by_severity[severity] = by_severity.get(severity, 0) + 1
        key = f"{status}_{severity}"
        by_status_severity[key] = by_status_severity.get(key, 0) + 1

    score = val.overall_score

    lines = [
        f"Total findings: {total}",
        f"Overall score: {score}",
        f"",
        f"By status: {by_status}",
        f"By severity: {by_severity}",
        f"",
        f"Detailed breakdown:",
    ]
    for key, count in sorted(by_status_severity.items()):
        lines.append(f"  {key}: {count}")

    return "\n".join(lines)
